insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_135'
from (values
('127.886.d.1.A',3,'Two interns compare how business greetings, gift giving and meeting times differ in Japan and Brazil. They are:','["identifying similarities and differences in international cultures", "assuming all cultures match", "ignoring culture", "skipping research"]'::jsonb,0,'Cultural comparison.','original'),
('127.886.d.1.A',4,'Before a partner visit from another country, a logistics firm studies local customs mainly to:','["avoid the visit", "avoid misunderstandings and build trust", "shorten the contract", "save money on lunch"]'::jsonb,1,'Cultural awareness.','original'),
('127.886.d.1.B',3,'A trainee lists the largest ports, rail hubs and consumer markets in Asia, Europe and the Americas. She is explaining:','["a single market", "no markets", "the variety of world markets", "local shops only"]'::jsonb,2,'World markets.','original'),
('127.886.d.1.B',4,'Emerging markets are of interest to distributors because they often show:','["no trade", "no demand", "no growth", "fast growth and rising consumer demand"]'::jsonb,3,'Market growth.','original'),
('127.886.d.1.C',3,'A shipper changes the packaging colors and language on a product for a new foreign market after learning local preferences. This shows:','["marketing factors and practices that impact other cultures", "one design for all", "ignoring culture", "no research"]'::jsonb,0,'Adapt marketing.','original'),
('127.886.d.1.C',4,'A product name that sounds fine in English but has a poor meaning abroad shows why firms must:','["ignore feedback", "research language and culture before launching", "avoid exporting", "skip research"]'::jsonb,1,'Localize.','original'),
('127.886.d.2.A',3,'A student writes a glossary with ''freight'', ''warehousing'', ''cross-docking'' and ''inventory turnover''. She is:','["guessing meanings", "avoiding terms", "defining terms associated with the distribution and logistics industries", "skipping vocabulary"]'::jsonb,2,'Vocabulary.','original'),
('127.886.d.2.A',4,'Cross-docking is a practice in which goods are:','["stored for months", "destroyed", "painted", "moved from inbound to outbound trucks with little or no storage"]'::jsonb,3,'Cross-dock.','original'),
('127.886.d.2.B',3,'A career fair handout explains that distribution and logistics includes trucking, warehousing, air cargo, rail and freight forwarding. It is identifying:','["the scope of the distribution and logistics industries and industry sectors", "only retail", "no sectors", "one narrow job"]'::jsonb,0,'Scope.','original'),
('127.886.d.2.B',4,'A freight forwarder is a business that:','["builds roads", "arranges shipments between shippers and carriers", "makes trucks", "prints maps"]'::jsonb,1,'Freight forwarder.','original'),
('127.886.d.2.C',3,'A class reads about the rise of containerized shipping and the recent growth of same-day delivery. They are identifying:','["only fiction", "no issues", "significant historical and current issues in the distribution and logistics industries", "only old news"]'::jsonb,2,'History and current issues.','original'),
('127.886.d.2.C',4,'Container shipping changed global trade mainly by:','["slowing ports", "ending shipping", "shrinking boats", "standardizing loads so cargo moves faster between ships, trains and trucks"]'::jsonb,3,'Containerization.','original'),
('127.886.d.2.D',3,'A planner sketches how drones, autonomous trucks and robotic warehouses could reshape delivery in ten years. She is identifying:','["potential future scenarios for the distribution and logistics industries", "nothing", "a recipe", "the distant past"]'::jsonb,0,'Future scenarios.','original'),
('127.886.d.2.D',4,'A likely future trend in warehouses is:','["no inventory", "more automation and robotic picking", "no workers ever", "fewer computers"]'::jsonb,1,'Automation.','original'),
('127.886.d.2.E',3,'A company adds tracking sensors to containers and expands to overseas suppliers. This shows how:','["trade is shrinking", "nothing changes", "emerging technology and globalization impact the distribution and logistics industries", "technology is irrelevant"]'::jsonb,2,'Tech and globalization.','original'),
('127.886.d.2.E',4,'One effect of globalization on logistics is:','["shorter supply chains only", "less shipping", "no trade", "longer supply chains that need more coordination"]'::jsonb,3,'Longer chains.','original'),
('127.886.d.2.F',3,'Students compare driver shortages in trucking with port congestion in ocean shipping. They are:','["comparing and contrasting issues affecting the distribution and logistics industries", "describing one issue only", "ignoring issues", "writing a story"]'::jsonb,0,'Compare issues.','original'),
('127.886.d.2.F',4,'Port congestion differs from driver shortages in that congestion mainly delays:','["paint drying", "cargo waiting at terminals, while shortages limit trucks available to move it", "school buses", "nothing"]'::jsonb,1,'Different bottlenecks.','original'),
('127.886.d.3.A',3,'A class studies why nations trade: resources one country lacks, cheaper production elsewhere and larger markets. They are identifying:','["no reasons", "reasons to avoid trade", "reasons for world trade and globalization", "a single reason"]'::jsonb,2,'Why trade.','original'),
('127.886.d.3.A',4,'Comparative advantage explains why countries trade because they:','["only import", "produce everything", "never trade", "specialize in what they produce relatively best"]'::jsonb,3,'Specialization.','original'),
('127.886.d.3.B',3,'A report explains how a port strike, a trade war or a sanction can change what stores can stock. This is identifying:','["the political impact of distribution and logistics", "only weather", "no politics", "no impact"]'::jsonb,0,'Political impact.','original'),
('127.886.d.3.B',4,'Trade sanctions affect logistics firms by:','["lowering all prices", "limiting what and where they may ship", "opening all ports", "removing paperwork"]'::jsonb,1,'Sanctions.','original'),
('127.886.d.3.C',3,'A compliance officer reviews labor, safety and customs laws to see how they affect warehouse operations and shipping routes. She is:','["breaking laws", "guessing", "reviewing regulations and major laws to evaluate their impact on the industry", "ignoring laws"]'::jsonb,2,'Review laws.','original'),
('127.886.d.3.C',4,'A company that fails to follow cargo regulations risks:','["a bonus", "free freight", "faster customs", "fines, delays and loss of shipping privileges"]'::jsonb,3,'Compliance risk.','original'),
('127.886.d.3.D',3,'Each morning a supply-chain analyst reads trade journals and freight news to learn about delays and rate changes. She is:','["reading written material to stay abreast of current issues", "ignoring news", "only watching TV", "avoiding reading"]'::jsonb,0,'Stay informed.','original'),
('127.886.d.3.D',4,'Staying current with industry news helps a logistics planner:','["slow work", "anticipate disruptions and adjust plans", "ignore risk", "miss changes"]'::jsonb,1,'Anticipate.','original'),
('127.886.d.3.E',3,'Faced with a closed bridge, a dispatcher lists three alternate routes, compares time and cost and picks the best. She is using:','["guessing", "a coin flip", "critical-thinking skills to identify and organize alternatives and evaluate options", "no thinking"]'::jsonb,2,'Critical thinking.','original'),
('127.886.d.3.E',4,'The best way to compare alternatives is to:','["pick the first", "choose randomly", "ignore costs", "list the options and weigh each against cost, time and risk"]'::jsonb,3,'Evaluate options.','original'),
('127.886.d.3.F',3,'A manager reviews on-time delivery rates and checks that a hired trucking contractor meets the terms of its contract. She is:','["evaluating performance and contract compliance of contractors and service providers", "skipping reviews", "ignoring contracts", "guessing"]'::jsonb,0,'Contract compliance.','original'),
('127.886.d.3.F',4,'A contractor who repeatedly misses delivery windows should:','["be given more loads", "be addressed using contract terms and possibly replaced", "be rewarded", "be ignored"]'::jsonb,1,'Enforce the contract.','original'),
('127.886.d.4.A',3,'A clerk finds a pricing error in the shop''s favor and reports it to a manager instead of keeping quiet. This shows:','["dishonesty", "a legal shortcut", "workplace ethical and legal responsibilities", "ignoring rules"]'::jsonb,2,'Ethics.','original'),
('127.886.d.4.A',4,'Accepting a gift from a supplier in exchange for a contract could be:','["encouraged", "acceptable", "required", "an ethics and legal violation"]'::jsonb,3,'Conflict of interest.','original'),
('127.886.d.4.B',3,'A new hire greets customers politely, silences his phone in meetings and thanks coworkers. He is:','["using proper etiquette and behavior", "interrupting", "ignoring others", "being rude"]'::jsonb,0,'Etiquette.','original'),
('127.886.d.4.B',4,'Good workplace etiquette includes:','["arriving late", "respecting others'' time and personal space", "interrupting", "gossiping"]'::jsonb,1,'Respect.','original'),
('127.886.d.4.C',3,'A warehouse supervisor expects clean uniforms, closed-toe boots, hair tied back near machines and good hygiene. She is identifying:','["skipping safety", "any outfit", "appropriate personal appearance and health habits", "no standards"]'::jsonb,2,'Appearance and health.','original'),
('127.886.d.4.C',4,'Hair tied back and no loose jewelry near conveyors helps:','["look worse", "slow work", "cause injuries", "prevent entanglement injuries"]'::jsonb,3,'Safety appearance.','original'),
('127.886.d.4.D',3,'A dispatcher repeats a driver''s problem back, asks questions and then writes a short email summarizing the plan. She is:','["practicing written and oral communication and effective listening", "ignoring the driver", "avoiding contact", "guessing"]'::jsonb,0,'Listening and writing.','original'),
('127.886.d.4.D',4,'A driver explains a late load, and the dispatcher nods, asks a clarifying question and restates the problem. That is an example of:','["looking at a phone while he talks", "active listening, which means paying attention and summarizing what was said", "interrupting to give orders", "tuning out until he finishes"]'::jsonb,1,'Active listening.','original'),
('127.886.d.4.E',3,'A student reads a technical manual on pallet racking load limits and explains it in her own words. She is:','["guessing", "avoiding reading", "comprehending technical reading materials common to the distribution and logistics industries", "skipping manuals"]'::jsonb,2,'Technical reading.','original'),
('127.886.d.4.E',4,'A rated load limit on a rack means:','["the paint amount", "the minimum weight", "the price", "the maximum weight the rack can safely hold"]'::jsonb,3,'Load rating.','original'),
('127.886.d.4.F',3,'Before a presentation on dock safety, Eli outlines his points, rehearses and practices short answers for questions he might get. He is:','["employing sound writing and preparation skills for prepared and extemporaneous oral presentations", "avoiding practice", "not preparing", "reading blindly"]'::jsonb,0,'Prepare to speak.','original'),
('127.886.d.4.F',4,'An extemporaneous speech differs from a prepared speech because it is:','["memorized exactly", "given with little or no advance preparation", "read from a script", "written word for word"]'::jsonb,1,'Extemporaneous.','original'),
('127.886.d.4.G',3,'During a team huddle, a lead speaks clearly, makes eye contact and uses a steady pace. She is demonstrating:','["mumbling", "whispering", "speaking skills", "poor speaking"]'::jsonb,2,'Speaking skills.','original'),
('127.886.d.4.G',4,'Good speakers keep an audience engaged by:','["staring at the floor", "speaking too fast", "reading from slides", "using eye contact, clear volume and a steady pace"]'::jsonb,3,'Engagement.','original'),
('127.886.d.5.A',3,'A student lists areas where research and development happens, such as new packaging materials, safer forklifts and route-planning software. She is:','["defining major fields of research and development", "naming one field only", "avoiding research", "guessing"]'::jsonb,0,'R&D fields.','original'),
('127.886.d.5.A',4,'Research and development in logistics often aims to:','["raise costs", "improve efficiency, safety or cost", "avoid change", "slow deliveries"]'::jsonb,1,'R&D goals.','original'),
('127.886.d.5.B',3,'A researcher uses trade journals, industry databases and interviews with warehouse managers to study new tracking tools. She is:','["guessing", "using one resource", "demonstrating proficiency in using a variety of resources for research and development", "skipping research"]'::jsonb,2,'Use varied resources.','original'),
('127.886.d.5.B',4,'Using several sources in research helps a student:','["avoid checking", "hide errors", "limit ideas", "confirm facts and see different viewpoints"]'::jsonb,3,'Multiple sources.','original'),
('127.886.d.5.C',3,'A team tests whether a new packing method reduces damage by running trials, recording results and comparing them to a control. They are describing:','["the scientific method of research", "a random guess", "an opinion", "a rumor"]'::jsonb,0,'Scientific method.','original'),
('127.886.d.5.C',4,'In the scientific method, a hypothesis is:','["a final result", "a testable prediction", "a proven law", "a survey"]'::jsonb,1,'Hypothesis.','original'),
('127.886.d.6.A',3,'A team writes up a plan to pilot barcode scanning at one dock, stating its goal, budget and schedule. They are:','["guessing", "avoiding goals", "discussing project proposals", "skipping planning"]'::jsonb,2,'Project proposal.','original'),
('127.886.d.6.A',4,'Before the dock team can get approval to try new scanners, the proposal must spell out:','["only the crew''s favorite colors", "only a map of the lot", "a joke and a menu", "the project goal, the timeline and the budget"]'::jsonb,3,'Proposal parts.','original'),
('127.886.d.6.B',3,'A student keeps a log of each shipment she handles, with dates, quantities and signatures. She is:','["developing and maintaining records", "avoiding records", "tossing papers", "ignoring logs"]'::jsonb,0,'Records.','original'),
('127.886.d.6.B',4,'Accurate shipping records are valuable because they:','["cause disputes", "help resolve disputes and track performance", "slow work", "hide errors"]'::jsonb,1,'Record value.','original'),
('127.886.d.6.C',3,'A clerk records weekly pallet counts and turns the numbers into a bar chart. She is:','["ignoring numbers", "avoiding data", "collecting and organizing data in graphs, tables, charts and plots", "guessing"]'::jsonb,2,'Organize data.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_135'
from (values
('127.886.d.6.C',4,'Hana wants a chart showing how weekly damaged-carton counts rose and fell over six months. The best choice is:','["a list of drivers", "a pie chart of names", "a map of the lot", "a line graph, which shows change over time"]'::jsonb,3,'Line graph.','original'),
('127.886.d.6.D',3,'A manager reads a chart showing late deliveries rise every Friday and concludes staffing is thin that day. She is:','["analyzing and interpreting data from graphs, tables, charts and plots", "guessing", "ignoring the chart", "misreading data"]'::jsonb,0,'Interpret data.','original'),
('127.886.d.6.D',4,'A rising trend on a chart of damage claims suggests:','["a perfect year", "a growing problem that needs investigating", "fewer claims", "no problem"]'::jsonb,1,'Read the trend.','original'),
('127.886.d.6.E',3,'The warehouse keeps a journal of purchases, an inventory count and an income statement for the year. This is:','["a budget only", "no records", "maintaining appropriate financial records such as journals, inventories and income statements", "random lists"]'::jsonb,2,'Financial records.','original'),
('127.886.d.6.E',4,'An income statement shows a company''s:','["employee names", "truck colors", "delivery routes", "revenue, expenses and profit over a period"]'::jsonb,3,'Income statement.','original'),
('127.886.d.6.F',3,'At the end of a project, a class checks whether it hit its objectives and whether it stayed in budget. They are:','["conducting formative, summative and financial analyses of project learning objectives", "ignoring results", "skipping evaluation", "guessing"]'::jsonb,0,'Project evaluation.','original'),
('127.886.d.6.F',4,'A summative analysis is done:','["only during lunch", "at the end to judge overall results", "never", "at the start"]'::jsonb,1,'Summative.','original'),
('127.886.d.6.G',3,'A student reviews the steps to earn a commercial driver license, including the knowledge tests and skills test. She is:','["ignoring tests", "guessing", "reviewing CDL preparation guidelines", "avoiding the license"]'::jsonb,2,'CDL prep.','original'),
('127.886.d.6.G',4,'A CDL is required to operate:','["a scooter", "a bicycle", "a lawn mower", "large commercial vehicles such as tractor-trailers and buses"]'::jsonb,3,'CDL need.','original'),
('127.886.d.6.H',3,'An instructor explains the CDL general knowledge test, the air brakes test and the road skills exam to the class. She is:','["explaining CDL guidelines in preparation for testing", "guessing", "skipping steps", "avoiding testing"]'::jsonb,0,'CDL testing.','original'),
('127.886.d.6.H',4,'The vehicle inspection portion of a CDL skills test checks that a driver can:','["paint the truck", "find and explain defects before driving", "ignore defects", "skip checks"]'::jsonb,1,'Pre-trip test.','original'),
('127.886.d.7.A',3,'An office assistant uses a calendar app, email and a web browser to schedule pickups and look up carriers. She is:','["avoiding technology", "using paper only", "using personal management software, email applications and Internet applications", "skipping email"]'::jsonb,2,'Everyday software.','original'),
('127.886.d.7.A',4,'A shared digital calendar helps a dispatch team:','["hide shifts", "lose appointments", "slow communication", "see schedules and avoid double-booking drivers"]'::jsonb,3,'Shared calendar.','original'),
('127.886.d.7.B',3,'A clerk drafts a letter, stores customer data in a database, builds a rate sheet and presents results with slides. She is:','["using word-processing, database, spreadsheet and presentation software", "using only email", "using none", "using one tool"]'::jsonb,0,'Office software.','original'),
('127.886.d.7.B',4,'A spreadsheet formula is best used to:','["edit video", "calculate totals automatically from entered numbers", "send mail", "write a letter"]'::jsonb,1,'Spreadsheet formulas.','original'),
('127.886.d.7.C',3,'Teams in three cities hold a video conference and edit a shared load plan together online. They are using:','["fax machines", "paper only", "collaborative or virtual meeting software", "no software"]'::jsonb,2,'Virtual meetings.','original'),
('127.886.d.7.C',4,'A benefit of virtual meeting software for a logistics team is:','["slower decisions", "no communication", "more travel", "people in different locations can meet without traveling"]'::jsonb,3,'Remote teamwork.','original'),
('127.886.d.7.D',3,'A planner uses a digital map layer and satellite positioning to find the closest depot to a customer. She is using:','["Geographic Information Systems and Global Positioning Systems", "a compass only", "a paper atlas only", "a guess"]'::jsonb,0,'GIS and GPS.','original'),
('127.886.d.7.D',4,'A benefit of GIS to a distributor is that it can:','["draw cartoons", "map delivery points and analyze the best routes", "paint trucks", "print tickets"]'::jsonb,1,'GIS benefit.','original'),
('127.886.d.7.E',3,'A warehouse manager uses software to schedule shifts and track the forklifts and racks the company owns. She is using:','["no software", "a notebook only", "computer-based equipment to manage human resources and physical assets", "only memory"]'::jsonb,2,'Manage assets.','original'),
('127.886.d.7.E',4,'Tracking physical assets in software helps a company:','["hide costs", "avoid maintenance", "lose equipment", "know where equipment is and when it needs service"]'::jsonb,3,'Asset tracking.','original'),
('127.886.d.7.F',3,'A receiving clerk scans each carton''s barcode into the system so the item is counted and located. She is using:','["technology applications such as barcode systems to identify and track goods", "handwriting only", "no tracking", "guessing"]'::jsonb,0,'Barcode tracking.','original'),
('127.886.d.7.F',4,'A barcode scanner speeds up receiving because it:','["adds errors", "reads item data instantly and reduces typing errors", "slows counting", "blocks tracking"]'::jsonb,1,'Barcode speed.','original'),
('127.886.d.7.G',3,'A customer opens a phone app to watch a delivery truck move along the map toward their address. This is:','["no tracking", "guessing arrival", "using mobile applications such as GPS to track goods and shipments", "mailing a letter"]'::jsonb,2,'Mobile tracking.','original'),
('127.886.d.7.G',4,'GPS tracking of shipments lets a company:','["avoid updates", "lose cargo", "hide shipments", "give customers accurate delivery estimates"]'::jsonb,3,'Tracking benefit.','original'),
('127.886.d.8.A',3,'A manager notices that pickers walk far between items and uses the pick-time data to find the slowest area of the warehouse. She is:','["using data to identify areas of operation that need improvement", "ignoring data", "guessing", "blaming workers"]'::jsonb,0,'Data shows slow spots.','original'),
('127.886.d.8.A',4,'Data-driven improvement starts by:','["skipping tracking", "measuring current performance to find where problems are", "ignoring metrics", "guessing"]'::jsonb,1,'Measure first.','original'),
('127.886.d.8.B',3,'After studying the slow aisle, a team proposes slotting fast-moving items near the dock and batching orders. They are:','["ignoring options", "copying old methods", "identifying alternative processes and procedures to improve and optimize business operations", "making no changes"]'::jsonb,2,'Alternatives.','original'),
('127.886.d.8.B',4,'Batch picking improves efficiency because it:','["adds more trips", "adds paperwork only", "slows picking", "combines several orders into one trip through the aisles"]'::jsonb,3,'Batch picking.','original'),
('127.886.d.8.C',3,'Using last year''s sales numbers, a planner moves the fastest sellers to the front racks and shortens delivery routes. She is:','["making data-based decisions on optimizing storage space and distribution routes", "guessing", "ignoring numbers", "adding clutter"]'::jsonb,0,'Data decisions.','original'),
('127.886.d.8.C',4,'Which choice best reflects a data-based decision?','["Choosing a route by hunch", "Reassigning a route after reviewing delivery times for three months", "Never changing routes", "Choosing the longest route"]'::jsonb,1,'Use evidence.','original'),
('127.886.d.9.A',3,'A supervisor walks the dock, spots a wet floor, puts out a sign and has it mopped. She is:','["hiding hazards", "ignoring hazards", "identifying, assessing and controlling hazards to maintain safe and healthy working conditions", "adding hazards"]'::jsonb,2,'Control hazards.','original'),
('127.886.d.9.A',4,'The best order for dealing with a hazard is to:','["wait for injury", "ignore it", "only post a sign later", "identify it, assess the risk and then control it"]'::jsonb,3,'Identify, assess, control.','original'),
('127.886.d.9.B',3,'A trainer reviews each part of the company safety program and explains why each part, such as training and hazard reporting, matters. She is:','["stating the role and summarizing the benefits of each component in a health, safety and environmental management system", "no benefits", "only one part", "no role"]'::jsonb,0,'Safety system.','original'),
('127.886.d.9.B',4,'One benefit of a safety and health management system is that it:','["adds accidents", "reduces injuries and costs over time", "hides risk", "raises injuries"]'::jsonb,1,'System benefits.','original'),
('127.886.d.9.C',3,'A warehouse team practices what to do when a pallet of chemicals leaks, including who calls for help and where to meet. They are:','["panicking", "ignoring emergencies", "demonstrating emergency procedures to reduce and mitigate workplace accidents", "skipping drills"]'::jsonb,2,'Emergency drills.','original'),
('127.886.d.9.C',4,'During a spill emergency, workers should first:','["ignore it", "clean it bare-handed", "spread it around", "get to safety and alert the response team"]'::jsonb,3,'Safety first.','original'),
('127.886.d.9.D',3,'A safety lead inspects the ladders, the pallet jacks and the gloves in the supply room and logs what she finds. She is:','["performing tool, equipment, facility and personal protective equipment audits and inspections", "skipping tools", "ignoring PPE", "avoiding audits"]'::jsonb,0,'Audits.','original'),
('127.886.d.9.D',4,'Damaged PPE found during an audit should be:','["used anyway", "replaced before it is used again", "taped", "hidden"]'::jsonb,1,'Replace damaged PPE.','original'),
('127.886.d.9.E',3,'A trainee reads about OSHA rules that require guarding, training and hazard communication. She is:','["ignoring laws", "avoiding rules", "identifying rules and laws designed to promote safety and health in the workplace", "breaking rules"]'::jsonb,2,'Safety laws.','original'),
('127.886.d.9.E',4,'The U.S. agency that sets and enforces workplace safety standards is:','["the IRS", "NASA", "the FCC", "OSHA"]'::jsonb,3,'OSHA role.','original'),
('127.886.d.9.F',3,'A trainee practices chest compressions on a mannequin and learns how to treat a cut with a bandage. She is demonstrating:','["knowledge of first aid and cardiopulmonary resuscitation procedures", "ignoring injured people", "no first aid", "avoiding emergencies"]'::jsonb,0,'First aid and CPR.','original'),
('127.886.d.9.F',4,'When someone collapses and isn''t breathing, the first steps are to:','["walk away", "call emergency services and start CPR", "wait", "give a drink"]'::jsonb,1,'Act quickly.','original'),
('127.886.d.10.A',3,'A packaging tester drops a boxed item, shakes it on a vibration table and stacks weights on top to see if it survives shipping. She is:','["skipping packaging", "guessing", "determining risks or damage from normal rigors such as compression, shock, drop and moisture", "avoiding tests"]'::jsonb,2,'Package testing.','original'),
('127.886.d.10.A',4,'A drop test on a package is used to:','["speed delivery", "improve color", "raise price", "check if contents survive shock during handling"]'::jsonb,3,'Shock test.','original'),
('127.886.d.10.B',3,'A shipper checks labels, placards and special rules before moving a pallet of flammable paint. She is discussing:','["the transporting and handling of hazardous materials", "no labels", "ordinary freight", "no rules"]'::jsonb,0,'Hazmat handling.','original'),
('127.886.d.10.B',4,'Hazardous materials must be marked with:','["random stickers", "placards and labels that identify the hazard", "no markings", "only a company logo"]'::jsonb,1,'Hazmat labels.','original'),
